import{_ as a,o as r,c as t,a6 as c}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"TikTools 4.2.1-rc.3 预发行版","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.3 预发行版","docId":"releases.4.2.1-rc.3","translationKey":"releases.4.2.1-rc.3","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3fa36e41656e0c6d288286b333984d1334fb5174054cdadb489464890c6196ea","translationRevision":"e8485f902372b76bfb28f0771c2a014ddc4b68dc89cf5d5ef99628a2bde4b119","order":30},"headers":[],"relativePath":"zh/releases/4.2.1-rc.3.md","filePath":"zh/releases/4.2.1-rc.3.md","lastUpdated":1794611623000}'),o={name:"zh/releases/4.2.1-rc.3.md"};function l(i,e,s,d,n,h){return r(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="tiktools-421-rc3" tabindex="-1">TikTools 4.2.1-rc.3 预发行版 <a class="header-anchor" href="#tiktools-421-rc3" aria-label="Permalink to &quot;TikTools 4.2.1-rc.3 预发行版 {#tiktools-421-rc3}&quot;">​</a></h1><h2 id="goal-release-status-and-prerequisites" tabindex="-1">目标、发布状态与前置条件 <a class="header-anchor" href="#goal-release-status-and-prerequisites" aria-label="Permalink to &quot;目标、发布状态与前置条件 {#goal-release-status-and-prerequisites}&quot;">​</a></h2><p>根据 2026 年 11 月 13 日报告，RC3 是已发布的预发行版。使用备份和独立测试配置，评估 RC2 之后的 Linux 桌面变化。它是候选版，并非稳定通道更新。从<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">发布列表</a>下载已发布的 AppImage、DEB 或便携资源及其 <code>SHA256SUMS.txt</code>；记录中的包由本地构建。</p><p>Cloud 分区恢复和协作仍属实验性。安装不会部署后端迁移，也不能证明生产账户兼容。</p><h2 id="changes-available-in-rc3" tabindex="-1">RC3 中可用的变化 <a class="header-anchor" href="#changes-available-in-rc3" aria-label="Permalink to &quot;RC3 中可用的变化 {#changes-available-in-rc3}&quot;">​</a></h2><ul><li>保留 RC2 对并发比较读取的修正，以及带原生失败原因的本地重试。</li><li>变量持久化文本、数字、布尔、列表和本地秘密类型。原子保存拒绝已变化的宿主或过期编辑器修订，同时保留既有模板文本渲染。</li><li>秘密值保持遮蔽。切换宿主不能回退到旧写入路径；原生分类会将变为秘密之前已排队的值排除在后续发布和比较输出之外。</li><li>原生变量桥支持缓存比较、明确采纳单个变量和仅更新缓存的下载。应用时重新检查会话、同意、本地修订及缓存条目。</li></ul><p>保存变量仍在本地进行。RC3 不提供包含审查式发送/撤回及待处理冲突处理的完整变量更改按钮；该分区集成见 <a href="./4.2.2.html">4.2.2 源码说明</a>。将本地值标记为秘密，不会擦除先前发布的 Cloud 副本。</p><h2 id="check-the-published-candidate" tabindex="-1">检查已发布候选版 <a class="header-anchor" href="#check-the-published-candidate" aria-label="Permalink to &quot;检查已发布候选版 {#check-the-published-candidate}&quot;">​</a></h2><ol><li>验证包校验和及显示的 <code>4.2.1-rc.3</code> 版本。将测试配置和 XDG 目录与日常配置分开。</li><li>创建无害文本变量，例如 <code>demoGreeting = &quot;你好&quot;</code>，保存后重新加载。使用不敏感样例值检查其他明确类型。</li><li>打开更改，测试加载和本地重试。检查设置/团队及可选引导帮助，不要将缺少后端能力视为设置成功。</li><li>失败时报告确切操作、版本、原生原因和请求 ID。报告中不要包含令牌、邀请码或秘密值。</li></ol><h2 id="expected-result-evidence-and-recovery" tabindex="-1">预期结果、证据与恢复 <a class="header-anchor" href="#expected-result-evidence-and-recovery" aria-label="Permalink to &quot;预期结果、证据与恢复 {#expected-result-evidence-and-recovery}&quot;">​</a></h2><p>类型化本地值应在重新加载后保留，宿主或修订过期的编辑应明确失败。原始记录报告了原生变量/同步/对等检查、模拟宿主浏览器测试、沙箱 CLI 验证、安装器内容检查，以及空隔离配置下到达 frontend-ready 的启动。它不能证明已登录的生产同步或媒体播放正常。</p><p>记录中的 AppImage SHA-256 为 <code>4b11260836457350debf2680b230c52cea8408ddf17ccdc729d0025a62149b7e</code>；请验证实际下载附带的校验和文件。失败时保留复制配置，并在重试恢复操作前使用<a href="./../user/preferences/troubleshooting.html">故障排查</a>。</p><p>昵称邀请依赖后端 <code>6a69c99</code> 及迁移 <code>20261113000001_remote_invitation_recipients.sql</code>。旧记录观察到人员路由缺失；这里不声称执行了新的生产探测。自动化 Cloud 传输、叠加层修订及其余协作审计尚未完成，历史 SQLite 锁持有者仍未知。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.3.md" target="_blank" rel="noreferrer">原始发布记录</a>作为带日期证据保留。返回<a href="./">发行说明索引</a>。</p>',14)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
